/* оценка попытки — с повторами букв, как положено: сначала «на месте», потом «есть» по остатку */
function оценить(попытка, ответ){
  const итог = Array(5).fill('нет'), остаток = {};
  for(let j = 0; j < 5; j++){ if(попытка[j] === ответ[j]) итог[j] = 'место'; else остаток[ответ[j]] = (остаток[ответ[j]] || 0) + 1; }
  for(let j = 0; j < 5; j++) if(итог[j] !== 'место' && остаток[попытка[j]]){ итог[j] = 'есть'; остаток[попытка[j]]--; }
  return итог;
}

