  const части = [];
  for(const строка of ['абвгдежз', 'ийклмноп', 'рстуфхцч', 'шщъыьэюя']){
    for(const б of строка){ const с = сост[б]; части.push({текст: '\u2009' + б.toUpperCase() + '\u2009', цвет: с ? '#ffffff' : '#151c2e', фон: с ? ЦВЕТ[с] : '#e6eaf0', жирный: true}, {текст: '\u2009'}); }
    части.push({текст: '\n'});
  }
  панель.поле('клавиатура', части);
}
function статистика(){
  const с = хранилище.взять('стат', null) || {сыграно: 0, побед: 0, серия: 0, лучшая: 0, попыток: [0, 0, 0, 0, 0, 0]};
  панель.список('стат', [['Сыграно дней', String(с.сыграно)], ['Побед', с.сыграно ? Math.round(100 * с.побед / с.сыграно) + '%' : '—'],
    ['Серия', String(с.серия)], ['Лучшая серия', String(с.лучшая)],
    ...с.попыток.map((n, i) => ['С ' + (i + 1) + '-й попытки', String(n)])]);
  return с;
}
function итогТекстом(){
  const стр = игра.попытки.map(п => оценить(п, игра.ответ).map(о => ЗНАЧОК[о]).join(''));
  return (игра.режим === 'Слово дня' ? 'Слово дня ' + датаДня(игра.день) : 'Слово (свободная игра)') + ' — ' + (игра.конец === 'победа' ? игра.попытки.length : 'X') + '/6\n' + стр.join('\n');
}
function сохранить(){ лист(игра.лист).запомнить(ПАМЯТЬ, игра); }

/* --- ход ----------------------------------------------------------------------- */
function попытка(слово){
  слово = норм(слово);
  if(!игра || игра.конец) return 'игра окончена — «Новая игра»';
  if(слово.length !== 5) return 'нужно слово ровно из пяти букв';
  if(!СЛОВА.has(слово)){ игра.черновик = ''; нарисоватьСтроку(игра.попытки.length); сохранить(); return 'слова «' + слово.toUpperCase() + '» нет в словаре — попытка не потрачена'; }
  игра.попытки.push(слово); игра.черновик = '';
  if(слово === игра.ответ) игра.конец = 'победа'; else if(игра.попытки.length >= ПОПЫТОК) игра.конец = 'мимо';
  нарисоватьСтроку(игра.попытки.length - 1); if(!игра.конец) нарисоватьСтроку(игра.попытки.length);
  шапка(); клавиатура(); сохранить();
  if(игра.конец){
    if(игра.режим === 'Слово дня' && !игра.засчитано){
      const с = статистика(); игра.засчитано = true;
      с.сыграно++; if(игра.конец === 'победа'){ с.побед++; с.попыток[игра.попытки.length - 1]++; с.серия = (с.день === игра.день - 1 ? с.серия : 0) + 1; с.лучшая = Math.max(с.лучшая, с.серия); } else с.серия = 0;
      с.день = игра.день; хранилище.положить('стат', с); статистика(); сохранить();
    }
    панель.поле('итог', итогТекстом());
    return игра.конец === 'победа' ? 'угадано! Итог для коллег — в поле «Поделиться».' : 'попытки кончились: было слово «' + игра.ответ.toUpperCase() + '».';
  }
  return 'попытка ' + игра.попытки.length + ' из 6';
}

/* --- обработчики --------------------------------------------------------------- */
function Старт(){
  статистика();
  let м = null; try { м = лист().память(ПАМЯТЬ); } catch(e){}
  if(м && м.ответ){ игра = м; клавиатура(); if(игра.конец){ панель.поле('итог', итогТекстом()); }
    панель.сообщение(игра.конец ? 'Партия на этом листе окончена. «Новая игра» — сыграть ещё.' : 'Партия на этом листе — продолжаем: попытка ' + (игра.попытки.length + 1) + ' из 6.'); }
  else { игра = null; панель.поле('клавиатура', [{текст: 'Нажмите «Новая игра».'}]); }
}
async function НоваяИгра(){
  const режим = параметры({}).режим || 'Слово дня';
  let своё = null; try { своё = лист().память(ПАМЯТЬ); } catch(e){}
  if(!своё && !(await областьПуста(0, С0, ряд(ПОПЫТОК - 1), стлб(4)))){
    if(!(await диалог.вопрос('На этом листе в B1:J13 уже что-то есть. Поле игры ляжет поверх и поменяет ширину столбцов. Лучше завести пустой лист (+ внизу). Всё равно положить здесь?'))) return;
  }
  const день = деньСегодня();
  if(режим === 'Слово дня'){
    const с = хранилище.взять('стат', null);
    if(с && с.день === день) панель.сообщение('Слово сегодняшнего дня вы уже отгадывали — сыграть можно, но в статистику пойдёт только первая партия.');
  }
  const ответ = режим === 'Слово дня' ? ответДня(день) : ответДня(Math.floor(Math.random() * ОТВЕТОВ));
  const засчитано = режим === 'Слово дня' && !!(хранилище.взять('стат', null) || {}).день && (хранилище.взять('стат', null) || {}).день === день;
  игра = {лист: книга.выделение ? книга.выделение.лист : книга.листы[0], режим, день, ответ, попытки: [], черновик: '', конец: null, засчитано};
  разметитьПоле(); await обновитьВысоты(); нарисоватьВсё(); клавиатура(); сохранить();
  панель.поле('итог', '');
  клетка(ряд(0), стлб(0)).выделить();
  панель.сообщение(режим + ': загадано существительное из пяти букв. Наберите слово в клетку первой строки.');
}
function ВвестиСлово(){
  const с = параметры({}).слово;
  панель.поле('слово', '');
  панель.сообщение(попытка(с));
  if(игра && !игра.конец) клетка(ряд(игра.попытки.length), стлб(0)).выделить();
}
function Правка(){
  const п = книга.повод;
  if(!игра || п.строение || п.откуда === 'плагин') return;
  let текущая = null, чужое = false;
  for(const к of п.клетки || []){
    if(к.лист !== игра.лист) continue;
    const r = к.строка - 1, c = к.столбец - 1;
    const k = (r - Р0) / 2, j = (c - С0) / 2;
    if(r < Р0 || c < С0 || r > ряд(ПОПЫТОК - 1) || c > стлб(4)) continue;
    if(!Number.isInteger(k) || !Number.isInteger(j) || k !== игра.попытки.length || игра.конец){ чужое = true; continue; }
    const т = норм(к.значение);
    if(т.length >= 2){ текущая = т.slice(0, 5); continue; }       /* слово целиком в одну клетку */
    const ч = (игра.черновик || '').padEnd(5, ' ').split('');
    ч[j] = т || ' ';
    игра.черновик = ч.join('').replace(/\s+$/, '');
    if(игра.черновик.replace(/ /g, '').length === 5) текущая = игра.черновик;
  }
  if(чужое){ нарисоватьВсё(); }
  if(текущая !== null){
    if(текущая.length === 5 && !текущая.includes(' ')){ панель.сообщение(попытка(текущая)); if(игра && !игра.конец) клетка(ряд(игра.попытки.length), стлб(0)).выделить(); }
    else { игра.черновик = текущая; нарисоватьСтроку(игра.попытки.length); сохранить(); }
  } else if(игра && !игра.конец){ нарисоватьСтроку(игра.попытки.length); сохранить(); }
}
